      <section class="section"><div class="section-head"><h2>教育经历</h2><span>支持添加多段教育背景</span></div><div class="section-body" id="educationList"><div class="entry"><div class="entry-label">教育经历 1</div><button class="remove-entry" type="button" aria-label="删除教育经历"><svg viewBox="0 0 24 24"><path d="M4 7h16M9 7V4h6v3M7 7l1 14h8l1-14"/></svg></button><div class="grid four"><div class="field"><label>学校</label><input value="华东师范大学" /></div><div class="field"><label>专业</label><input value="软件工程" /></div><div class="field"><label>学历</label><select><option>本科</option><option>硕士</option><option>博士</option></select></div><div class="field"><label>时间</label><input value="2019.09 - 2023.06" /></div></div></div><div class="entry"><div class="entry-label">教育经历 2</div><button class="remove-entry" type="button" aria-label="删除教育经历"><svg viewBox="0 0 24 24"><path d="M4 7h16M9 7V4h6v3M7 7l1 14h8l1-14"/></svg></button><div class="grid four"><div class="field"><label>学校</label><input value="上海交通大学" /></div><div class="field"><label>专业</label><input value="计算机技术" /></div><div class="field"><label>学历</label><select><option>硕士</option><option>本科</option><option>博士</option></select></div><div class="field"><label>时间</label><input value="2023.09 - 2025.06" /></div></div></div></div><div class="section-body" style="padding-top:0"><button class="add-entry" type="button" data-target="educationList">添加教育经历</button></div></section>
