<script setup>
import { onMounted } from 'vue'
import { validateResumeDraft } from '@/utils/agentValidation'

onMounted(() => {
  const toast=document.getElementById('toast');let toastTimer;function showToast(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2400)}
      const resumeNames={'product-manager':'产品经理-林晓雨','ai-product':'AI 产品方向-重点项目版',growth:'产品运营-增长方向',new:'未命名简历'},resumeId=new URLSearchParams(location.search).get('id')||'product-manager';document.getElementById('resumeTitle').value=resumeNames[resumeId]||resumeNames['product-manager'];
      function bindRemove(root=document){root.querySelectorAll('.remove-entry').forEach(button=>button.onclick=()=>{const list=button.closest('.section-body'),entries=list.querySelectorAll('.entry');if(entries.length<=1){showToast('至少保留一段经历');return}button.closest('.entry').remove();[...list.querySelectorAll('.entry-label')].forEach((label,index)=>label.textContent=label.textContent.replace(/\d+$/,String(index+1)))})}
      bindRemove();document.querySelectorAll('.add-entry').forEach(button=>button.addEventListener('click',()=>{const list=document.getElementById(button.dataset.target),education=button.dataset.target==='educationList',entry=document.createElement('div');entry.className='entry';entry.innerHTML=`<div class="entry-label">${education?'教育':'工作'}经历 ${list.querySelectorAll('.entry').length+1}</div><button class="remove-entry" type="button" aria-label="删除经历"><svg viewBox="0 0 24 24"><path d="M4 7h16M9 7V4h6v3M7 7l1 14h8l1-14"/></svg></button><div class="grid four">${education?'<div class="field"><label>学校</label><input placeholder="学校名称"></div><div class="field"><label>专业</label><input placeholder="专业名称"></div><div class="field"><label>学历</label><select><option>本科</option><option>硕士</option><option>博士</option></select></div><div class="field"><label>时间</label><input placeholder="开始时间 - 结束时间"></div>':'<div class="field"><label>公司</label><input placeholder="公司名称"></div><div class="field"><label>职位</label><input placeholder="职位名称"></div><div class="field"><label>时间</label><input placeholder="开始时间 - 结束时间"></div><div></div><div class="field full"><label>工作描述</label><textarea placeholder="描述职责与量化成果"></textarea></div>'}</div>`;list.appendChild(entry);bindRemove(entry);entry.querySelector('input').focus()}));
      function bindSkillRemove(root=document){root.querySelectorAll('.skill-remove').forEach(button=>button.onclick=()=>button.closest('.skill-tag').remove())}bindSkillRemove();document.getElementById('addSkill').addEventListener('click',()=>{const input=document.getElementById('skillInput'),value=input.value.trim();if(!value)return;const tag=document.createElement('span');tag.className='skill-tag';tag.append(document.createTextNode(value));const remove=document.createElement('button');remove.className='skill-remove';remove.type='button';remove.setAttribute('aria-label',`删除 ${value}`);remove.textContent='×';tag.appendChild(remove);document.getElementById('skillList').appendChild(tag);bindSkillRemove(tag);input.value='';input.focus()});
      document.getElementById('skillInput').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();document.getElementById('addSkill').click()}});
      document.getElementById('saveResume').addEventListener('click',()=>{const form=document.getElementById('resumeForm');if(!form.reportValidity())return;const validation=validateResumeDraft({title:document.getElementById('resumeTitle').value,name:document.getElementById('name').value,email:document.getElementById('email').value,targetRole:document.getElementById('targetRole').value,skillCount:document.querySelectorAll('#skillList .skill-tag').length});if(!validation.valid){showToast(validation.message);return}const title=document.getElementById('resumeTitle').value.trim();localStorage.setItem('resumeDraft',JSON.stringify({title,updated:new Date().toISOString()}));showToast('简历已保存')});
})
</script>

<style>
