    .main{padding:16px 0 88px}.breadcrumb{margin-bottom:12px;color:var(--light);font-size:10px}.breadcrumb a{text-decoration:none}.resume-overview{display:grid;grid-template-columns:minmax(0,1fr) 320px 210px;align-items:center;gap:24px;padding:18px 20px;border:1px solid var(--line);border-radius:8px;background:#fff;box-shadow:var(--shadow)}.resume-title-row{display:flex;align-items:center;gap:8px}.resume-title-input{width:min(360px,100%);padding:0;border:0;color:var(--primary);background:transparent;font-size:21px;font-weight:800}.resume-title-input:focus{outline:0;border-bottom:1px solid var(--blue)}.resume-badge{padding:2px 7px;border-radius:4px;color:var(--blue);background:var(--blue-soft);font-size:9px}.update-time{margin-top:5px;color:var(--light);font-size:10px}.progress-head{display:flex;justify-content:space-between;color:var(--muted);font-size:10px}.progress-head strong{color:var(--blue);font-size:18px}.progress-track{height:7px;margin-top:8px;border-radius:99px;background:#E5ECF5}.progress-value{width:90%;height:100%;border-radius:inherit;background:var(--blue)}.progress-note{margin-top:7px;color:var(--light);font-size:9px}.usage{text-align:right}.usage strong{display:block;color:var(--green);font-size:11px}.usage span{display:block;margin-top:5px;color:var(--light);font-size:9px}.usage a{display:inline-block;margin-top:6px;color:var(--blue);font-size:10px;text-decoration:none}
    .section{margin-top:13px;border:1px solid var(--line);border-radius:8px;background:#fff;box-shadow:var(--shadow);overflow:hidden}.section-head{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;padding:15px 20px 9px}.section-head h2{margin:0;color:var(--primary);font-size:15px}.section-head span{color:var(--light);font-size:9px}.section-body{padding:8px 20px 17px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.grid.four{grid-template-columns:repeat(4,minmax(0,1fr))}.field.full{grid-column:1/-1}.field label{display:block;margin-bottom:5px;color:#586A81;font-size:10px}.field input,.field select,.field textarea{width:100%;min-height:38px;padding:8px 10px;border:1px solid #D7E0EC;border-radius:5px;color:var(--text);background:#fff;font-size:11px}.field textarea{min-height:72px;resize:vertical}.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--blue);outline:3px solid rgba(43,127,255,.1)}.entry{position:relative;padding:13px;margin-bottom:10px;border-left:3px solid #D8E6FA;background:#F8FAFD}.entry:last-of-type{margin-bottom:0}.entry-label{margin-bottom:8px;color:var(--light);font-size:9px}.remove-entry{position:absolute;top:8px;right:8px;width:28px;height:28px;display:grid;place-items:center;border:0;border-radius:5px;color:#91A0B2;background:transparent}.remove-entry:hover{color:var(--red);background:#FCECEF}.remove-entry svg{width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:1.8}.add-entry{width:100%;height:36px;margin-top:10px;border:1px dashed #AFCBF2;border-radius:5px;color:var(--blue);background:#FBFDFF;font-size:10px}.add-entry:hover{background:var(--blue-soft)}
    .skill-wrap{display:flex;flex-wrap:wrap;gap:7px}.skill-tag{display:flex;align-items:center;gap:5px;padding:5px 8px;border-radius:5px;color:var(--blue);background:var(--blue-soft);font-size:10px}.skill-remove{width:16px;height:16px;padding:0;border:0;color:inherit;background:transparent}.skill-add{display:flex;gap:8px;margin-top:12px}.skill-add input{width:min(280px,100%);height:36px;padding:0 10px;border:1px solid #D7E0EC;border-radius:5px}.secondary,.primary{height:36px;padding:0 14px;border-radius:6px;font-size:11px;font-weight:700}.secondary{border:1px solid #CBD9EA;color:var(--primary);background:#fff}.primary{border:1px solid var(--blue);color:#fff;background:var(--blue)}.primary:hover{background:var(--blue-dark)}
