    @media(max-width:900px){.topbar-inner,.main,.savebar-inner{width:calc(100% - 32px)}.main-nav{display:none}.resume-overview{grid-template-columns:1fr 1fr}.usage{grid-column:1/-1;text-align:left}.grid.four{grid-template-columns:repeat(2,minmax(0,1fr))}}
    @media(max-width:620px){.resume-overview{grid-template-columns:1fr}.grid,.grid.four{grid-template-columns:1fr}.resume-title-input{font-size:18px}.section-head{padding-inline:14px}.section-body{padding-inline:14px}.save-note{display:none}.save-actions{width:100%}.save-actions button,.save-actions a{flex:1}.user strong{display:none}}
